import { createEntryPayload } from "./page";

export const EntriesPage = () => {
  const payload = createEntryPayload("entry-1", "Draft", ["new"], true);

  return <pre>{JSON.stringify(payload)}</pre>;
};

export interface CreateEntryPayload {
  entryId: string;
  name: string;
  tags: string[];
  enabled: boolean;
}

export const createEntryPayload = (
  entryId: string,
  name: string,
  tags: string[],
  enabled: boolean,
): CreateEntryPayload => ({
  entryId,
  name: name.trim(),
  tags,
  enabled,
});
